const { execSync } = require('child_process');
const ts = new Date().toISOString();
let n8n_ok = true;
let db_ok = false;
let container_ok = false;
try {
  const r = execSync('curl -sf http://127.0.0.1:5678/healthz 2>/dev/null', {timeout:5000}).toString();
  n8n_ok = r.includes('ok');
} catch(e) { n8n_ok = false; }
try {
  execSync('docker ps --filter name=impar-n8n --format "{{.Status}}" 2>/dev/null | grep -q Up', {timeout:5000});
  container_ok = true;
} catch(e) { container_ok = false; }
try {
  const db = process.env.HOME + '/.impar-n8n-core/../../../Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB/IMPAR_OS/database/impar.db';
  execSync(`sqlite3 "${db}" ".tables" 2>/dev/null`, {timeout:5000});
  db_ok = true;
} catch(e) { db_ok = false; }
return [{ json: { status: (n8n_ok && container_ok) ? 'healthy' : 'degraded', ai_used: false, timestamp: ts, checks: { n8n: n8n_ok, container: container_ok, database: db_ok } } }];
